loadPlayers = async (id: number, type: string) => {
    if (type === 'live') {
      setPlayerData([]);
      return;
    }
    if (type === 'history') {
      // @ts-ignore
      const stats = await window.api.getPlayerStats(id);
      setPlayerData(stats ? Object.values(stats) : []);
    } else {
      // @ts-ignore
      const data = await window.api.readJson(id, type);
      setPlayerData(data || []);
    }
  }

